cd /tmp/main-validate && python3 - <<'PY'
import re, glob, yaml
bad = []
for path in sorted(glob.glob("S*/E*.md")):
    text = open(path, encoding="utf-8").read()
    parts = re.split(r"^---\s*$", text, maxsplit=2, flags=re.MULTILINE)
    meta = yaml.safe_load(parts[1])
    body = parts[2].strip()
    summary = (meta.get("summary") or "").strip()
    # first paragraph of body
    first = body.split("\n\n")[0].strip()
    problems = []
    if not summary: problems.append("no summary")
    if summary != first: problems.append(f"summary/para mismatch: {first[:60]!r}")
    if not summary.endswith((".", "!", "?")): problems.append("summary punctuation")
    wc = len(summary.split())
    if not (15 <= wc <= 40): problems.append(f"summary wordcount {wc}")
    for key in ("title","summary","season","episode","status"):
        if key not in meta: problems.append(f"missing {key}")
    if problems:
        bad.append((path, problems))
print("episodes checked:", len(glob.glob("S*/E*.md")))
for p, pr in bad:
    print("DEFECT", p, pr)
print("clean" if not bad else f"{len(bad)} flagged")
PY
